  rs=[r for r in rows if r['engine_code']==code];gid=f'{code}-{field}';group={'group_id':gid,'engine_code':code,'field':field,'proposed_value':a['proposed_values_for_review'][field],'affected_row_ids':[r['research_row_id'] for r in rs],'row_count':len(rs),'consumer_row_count':sum(r['model_code']!='JLUL74' for r in rs),'direct_manufacturer_source_refs':source_refs,'additional_source_ids':new,'order_guide_excerpt_ids':a['order_guide_excerpt_ids'],'secondary_corroboration_refs':secondary,'derived_reasoning':reasoning,'confidence':'moderate','applicability':'MY2021 US Wrangler JL only; exact row IDs and retained positive guide cells, not other model years/markets/engines.','limitations':limitation,'human_adjudication_necessary':True,'evidence_assessment':'supported_derived_proposal_not_approved','owner_approval_status':'pending'};groups.append(group)
